import React, { useState, useEffect, useRef } from 'react';
import Icon from 'components/AppIcon';

const ARInterface = ({ arContent, uiAdaptations, onInteraction }) => {
  const [isARActive, setIsARActive] = useState(false);
  const [arSupported, setArSupported] = useState(false);
  const [currentView, setCurrentView] = useState('preview');
  const [modelRotation, setModelRotation] = useState({ x: 0, y: 0, z: 0 });
  const [zoomLevel, setZoomLevel] = useState(1);
  const [selectedCrossSection, setSelectedCrossSection] = useState(0);
  const videoRef = useRef(null);
  const canvasRef = useRef(null);

  useEffect(() => {
    // Check AR support
    if ('xr' in navigator) {
      navigator.xr?.isSessionSupported('immersive-ar').then(setArSupported);
    }
  }, []);

  const startARSession = async () => {
    try {
      if (arSupported) {
        // In a real implementation, this would start WebXR session
        setIsARActive(true);
        setCurrentView('ar');
        onInteraction(95); // High performance for AR engagement
      } else {
        // Fallback to camera preview mode
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsARActive(true);
          setCurrentView('camera');
        }
      }
    } catch (error) {
      console.error('AR session failed:', error);
      setCurrentView('3d-preview');
    }
  };

  const stopARSession = () => {
    setIsARActive(false);
    setCurrentView('preview');
    if (videoRef.current?.srcObject) {
      const tracks = videoRef.current.srcObject.getTracks();
      tracks.forEach(track => track.stop());
    }
  };

  const handleModelInteraction = (type, value) => {
    switch (type) {
      case 'rotate':
        setModelRotation(prev => ({ ...prev, ...value }));
        break;
      case 'zoom':
        setZoomLevel(value);
        break;
      case 'cross-section':
        setSelectedCrossSection(value);
        break;
    }
    onInteraction(88); // Good performance for 3D interactions
  };

  const getTextSize = () => {
    switch (uiAdaptations.textSize) {
      case 'large':
        return 'text-lg';
      case 'small':
        return 'text-sm';
      default:
        return 'text-base';
    }
  };

  return (
    <div className="space-y-6">
      {/* AR Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div 
            className="p-2 rounded-lg"
            style={{ backgroundColor: `${uiAdaptations.accentColor}20` }}
          >
            <Icon 
              name="Glasses" 
              size={20} 
              style={{ color: uiAdaptations.accentColor }}
            />
          </div>
          <div>
            <h2 className={`font-heading font-bold text-text-primary ${
              uiAdaptations.textSize === 'large' ? 'text-xl' : 'text-lg'
            }`}>
              AR Exploration
            </h2>
            <p className="text-sm text-text-secondary">
              {arContent.overlayInfo}
            </p>
          </div>
        </div>
        
        <div className="flex items-center space-x-2">
          {arSupported && (
            <div className="flex items-center space-x-1 px-2 py-1 bg-success-50 rounded-full">
              <div className="w-2 h-2 bg-success rounded-full animate-pulse"></div>
              <span className="text-xs text-success-700 font-medium">AR Ready</span>
            </div>
          )}
        </div>
      </div>

      {/* Main AR Interface */}
      <div className="relative">
        {currentView === 'preview' && (
          <div className="aspect-video bg-gradient-to-br from-surface-50 to-surface-100 rounded-lg border border-border overflow-hidden">
            {/* 3D Model Preview */}
            <div className="relative w-full h-full flex items-center justify-center">
              <div className="relative">
                {/* Mock 3D Surface */}
                <svg 
                  width="300" 
                  height="200" 
                  viewBox="0 0 300 200"
                  className="transform transition-transform duration-300"
                  style={{ 
                    transform: `rotateX(${modelRotation.x}deg) rotateY(${modelRotation.y}deg) scale(${zoomLevel})` 
                  }}
                >
                  {/* Grid base */}
                  <defs>
                    <pattern id="grid3d" width="20" height="20" patternUnits="userSpaceOnUse">
                      <path d="M 20 0 L 0 0 0 20" fill="none" stroke="#E5E7EB" strokeWidth="1"/>
                    </pattern>
                  </defs>
                  <rect width="100%" height="100%" fill="url(#grid3d)" opacity="0.3" />
                  
                  {/* 3D Surface representation */}
                  <path
                    d="M 50 150 Q 100 100 150 120 T 250 80 Q 280 60 300 40"
                    fill="none"
                    stroke={uiAdaptations.accentColor}
                    strokeWidth="3"
                    opacity="0.8"
                  />
                  <path
                    d="M 50 130 Q 100 80 150 100 T 250 60 Q 280 40 300 20"
                    fill="none"
                    stroke={uiAdaptations.accentColor}
                    strokeWidth="2"
                    opacity="0.6"
                  />
                  <path
                    d="M 50 170 Q 100 120 150 140 T 250 100 Q 280 80 300 60"
                    fill="none"
                    stroke={uiAdaptations.accentColor}
                    strokeWidth="2"
                    opacity="0.6"
                  />
                  
                  {/* Cross-section indicator */}
                  {selectedCrossSection > 0 && (
                    <line
                      x1={50 + selectedCrossSection * 2}
                      y1="20"
                      x2={50 + selectedCrossSection * 2}
                      y2="180"
                      stroke="#F59E0B"
                      strokeWidth="2"
                      strokeDasharray="5,5"
                    />
                  )}
                </svg>
                
                {/* Interaction hints */}
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                  <div className="bg-surface bg-opacity-90 rounded-lg p-3 text-center">
                    <Icon name="Hand" size={24} className="text-text-secondary mx-auto mb-2" />
                    <p className="text-sm text-text-secondary">
                      Tap to start AR experience
                    </p>
                  </div>
                </div>
              </div>
            </div>
            
            {/* AR Start Button */}
            <div className="absolute inset-0 flex items-center justify-center">
              <button
                onClick={startARSession}
                className="btn btn-primary px-6 py-3 text-base font-medium shadow-lg"
              >
                <Icon name="Play" size={20} className="mr-2" />
                {arSupported ? 'Start AR Experience' : 'Start 3D Preview'}
              </button>
            </div>
          </div>
        )}

        {currentView === 'camera' && (
          <div className="aspect-video bg-black rounded-lg overflow-hidden relative">
            <video
              ref={videoRef}
              autoPlay
              playsInline
              muted
              className="w-full h-full object-cover"
            />
            
            {/* AR Overlay */}
            <div className="absolute inset-0">
              <canvas
                ref={canvasRef}
                className="w-full h-full"
              />
              
              {/* AR Controls Overlay */}
              <div className="absolute top-4 left-4 right-4 flex justify-between">
                <div className="bg-black bg-opacity-50 rounded-lg p-2">
                  <p className="text-white text-sm">
                    Move device to explore the 3D function
                  </p>
                </div>
                <button
                  onClick={stopARSession}
                  className="bg-error bg-opacity-80 text-white p-2 rounded-lg"
                >
                  <Icon name="X" size={20} />
                </button>
              </div>
              
              {/* Virtual 3D Object Placeholder */}
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <div className="w-32 h-32 border-2 border-white border-dashed rounded-lg flex items-center justify-center">
                  <Icon name="Cube" size={48} className="text-white opacity-70" />
                </div>
              </div>
            </div>
          </div>
        )}

        {currentView === 'ar' && (
          <div className="aspect-video bg-black rounded-lg overflow-hidden relative">
            {/* Full AR Interface would be rendered here */}
            <div className="w-full h-full flex items-center justify-center">
              <div className="text-center text-white">
                <Icon name="Glasses" size={64} className="mx-auto mb-4 opacity-70" />
                <p className="text-lg font-medium mb-2">AR Session Active</p>
                <p className="text-sm opacity-70">
                  Look around to see the 3D mathematical function
                </p>
              </div>
            </div>
            
            <button
              onClick={stopARSession}
              className="absolute top-4 right-4 bg-error bg-opacity-80 text-white p-2 rounded-lg"
            >
              <Icon name="X" size={20} />
            </button>
          </div>
        )}
      </div>

      {/* Interactive Controls */}
      {(currentView === 'preview' || currentView === '3d-preview') && (
        <div className="space-y-4">
          <h3 className={`font-heading font-semibold text-text-primary ${getTextSize()}`}>
            3D Controls
          </h3>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Rotation Controls */}
            <div className="p-4 bg-surface-50 rounded-lg border border-border">
              <h4 className="text-sm font-medium text-text-primary mb-3">Rotation</h4>
              <div className="space-y-3">
                <div>
                  <label className="text-xs text-text-secondary">X-Axis</label>
                  <input
                    type="range"
                    min="-45"
                    max="45"
                    value={modelRotation.x}
                    onChange={(e) => handleModelInteraction('rotate', { x: parseInt(e.target.value) })}
                    className="w-full h-2 bg-surface-100 rounded-lg appearance-none cursor-pointer mt-1"
                  />
                </div>
                <div>
                  <label className="text-xs text-text-secondary">Y-Axis</label>
                  <input
                    type="range"
                    min="-45"
                    max="45"
                    value={modelRotation.y}
                    onChange={(e) => handleModelInteraction('rotate', { y: parseInt(e.target.value) })}
                    className="w-full h-2 bg-surface-100 rounded-lg appearance-none cursor-pointer mt-1"
                  />
                </div>
              </div>
            </div>

            {/* Zoom Control */}
            <div className="p-4 bg-surface-50 rounded-lg border border-border">
              <h4 className="text-sm font-medium text-text-primary mb-3">Zoom</h4>
              <input
                type="range"
                min="0.5"
                max="2"
                step="0.1"
                value={zoomLevel}
                onChange={(e) => handleModelInteraction('zoom', parseFloat(e.target.value))}
                className="w-full h-2 bg-surface-100 rounded-lg appearance-none cursor-pointer"
              />
              <div className="flex justify-between text-xs text-text-secondary mt-1">
                <span>0.5x</span>
                <span>{zoomLevel}x</span>
                <span>2x</span>
              </div>
            </div>
          </div>

          {/* Cross-Section Control */}
          <div className="p-4 bg-surface-50 rounded-lg border border-border">
            <h4 className="text-sm font-medium text-text-primary mb-3">Cross-Section Analysis</h4>
            <input
              type="range"
              min="0"
              max="100"
              value={selectedCrossSection}
              onChange={(e) => handleModelInteraction('cross-section', parseInt(e.target.value))}
              className="w-full h-2 bg-surface-100 rounded-lg appearance-none cursor-pointer"
            />
            <div className="flex justify-between text-xs text-text-secondary mt-1">
              <span>Start</span>
              <span>Position: {selectedCrossSection}%</span>
              <span>End</span>
            </div>
          </div>
        </div>
      )}

      {/* AR Instructions */}
      {!arSupported && (
        <div className="p-4 bg-warning-50 rounded-lg border border-warning-200">
          <div className="flex items-start space-x-3">
            <Icon name="AlertTriangle" size={20} className="text-warning-600 mt-0.5" />
            <div>
              <h4 className="font-medium text-warning-700 mb-1">
                AR Not Available
              </h4>
              <p className="text-sm text-warning-600">
                Your device doesn't support WebXR. You can still explore the 3D model using the preview mode above.
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Learning Objectives */}
      <div className="p-4 bg-primary-50 rounded-lg border border-primary-200">
        <h4 className="font-medium text-primary-700 mb-2">
          Learning Objectives
        </h4>
        <ul className="space-y-1 text-sm text-primary-600">
          <li className="flex items-center space-x-2">
            <Icon name="Check" size={14} />
            <span>Visualize how derivatives change across a 3D surface</span>
          </li>
          <li className="flex items-center space-x-2">
            <Icon name="Check" size={14} />
            <span>Understand the relationship between function and its derivative</span>
          </li>
          <li className="flex items-center space-x-2">
            <Icon name="Check" size={14} />
            <span>Explore cross-sections to see derivative behavior</span>
          </li>
        </ul>
      </div>
    </div>
  );
};

export default ARInterface;