import React, { useState, useEffect, useRef, useContext } from 'react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import Icon from 'components/AppIcon';
import { ProgressContext } from '../../contexts/ProgressContext';
import { DataContext } from '../../contexts/DataContext';
import { AIContext } from '../../contexts/AIContext';
import api from '../../lib/api';
import LoadingState from '../../components/ui/LoadingState';
import ErrorState from '../../components/ui/ErrorState';

import SessionHeader from './components/SessionHeader';
import ContentRenderer from './components/ContentRenderer';
import InteractiveQuiz from './components/InteractiveQuiz';
import ARInterface from './components/ARInterface';
import HintSystem from './components/HintSystem';
import NoteTaking from './components/NoteTaking';
import LiveInteractiveGame from './components/LiveInteractiveGame';
import SessionFeedbackPanel from './components/SessionFeedbackPanel';

const InteractiveLearningSession = () => {
  const { nodeId } = useParams();
  const navigate = useNavigate();
  const { learningNodes, updateNodeProgress, recordLearningSession, refreshProgress, loading: progressLoading } = useContext(ProgressContext);
  const { refreshData } = useContext(DataContext);
  const { 
    aiSettings,
    adaptiveMetrics,
    generateProceduralModule,
    generateAdaptiveQuiz,
    generateInteractiveGame,
    adaptMidSession,
    adaptLearning,
    aiConfigured,
    isGenerating,
  } = useContext(AIContext);

  const [lessonLoadError, setLessonLoadError] = useState(null);

  const [currentLearningNode, setCurrentLearningNode] = useState(null);
  const [currentLessonIndex, setCurrentLessonIndex] = useState(0);
  const [currentLessonData, setCurrentLessonData] = useState(null);
  const [availableLessons, setAvailableLessons] = useState([]);
  const [proceduralModule, setProceduralModule] = useState(null);
  const [generationStatus, setGenerationStatus] = useState({ state: 'idle', message: '' });
  const [sessionState, setSessionState] = useState({
    isActive: true,
    currentContentType: 'lesson', // 'lesson', 'quiz', 'ar', 'exercise'
    sessionDuration: 0,
    currentTopic: 'Loading topic...',
    difficulty: 'intermediate',
    learningStyle: aiSettings?.learningStyle || 'visual',
    progress: 0, // Will be set from currentLearningNode
    performance: 0 // Example: can be updated based on quiz results etc.
  });

  const getModuleCacheKey = (topicId) => {
    return `adaptiveLearnProceduralModule_${topicId}_${aiSettings.learningStyle}_${aiSettings.contentTheme}_${adaptiveMetrics.learningRate}`;
  };

  const loadCachedModule = (topicId) => {
    try {
      const cached = localStorage.getItem(getModuleCacheKey(topicId));
      if (cached) {
        return JSON.parse(cached);
      }
    } catch (error) {
      console.error('Error loading cached module:', error);
    }
    return null;
  };

  const saveCachedModule = (topicId, moduleData) => {
    try {
      localStorage.setItem(getModuleCacheKey(topicId), JSON.stringify(moduleData));
    } catch (error) {
      console.error('Error saving cached module:', error);
    }
  };

  useEffect(() => {
    if (!progressLoading && learningNodes.length > 0 && nodeId) {
      const node = learningNodes.find((n) => n.id === nodeId);
      if (!node) {
        console.warn(`Learning node with ID ${nodeId} not found.`);
        return;
      }

      setCurrentLearningNode(node);
      setProceduralModule(null);
      setGenerationStatus({ state: 'idle', message: '' });
      setLessonLoadError(null);

      api
        .getLessons(nodeId)
        .then((nodeLessons) => {
          const lessonCollection = nodeLessons?.lessons || nodeLessons?.sections;
          if (lessonCollection?.length) {
            setAvailableLessons(lessonCollection);
            setCurrentLessonData(lessonCollection[0]);
            setCurrentLessonIndex(0);
          } else {
            setAvailableLessons([]);
            setCurrentLessonData(null);
          }
        })
        .catch((err) => {
          setLessonLoadError(err.message);
          setAvailableLessons([]);
          setCurrentLessonData(null);
        });

      setSessionState((prev) => ({
        ...prev,
        currentTopic: node.title,
        progress: node.progress,
        difficulty: node.difficulty || prev.difficulty,
        sessionDuration: 0,
        isActive: true,
      }));
    } else if (!progressLoading && learningNodes.length > 0 && !nodeId) {
      const firstIncompleteNode = learningNodes.find((n) => !n.completed);
      if (firstIncompleteNode) {
        navigate(`/interactive-learning-session/${firstIncompleteNode.id}`, { replace: true });
      }
    }
  }, [nodeId, learningNodes, progressLoading, navigate]);

  useEffect(() => {
    setSessionState(prev => ({
      ...prev,
      learningStyle: aiSettings.learningStyle
    }));
  }, [aiSettings.learningStyle]);

  useEffect(() => {
    if (!currentLearningNode || !aiConfigured) {
      return;
    }

    let isMounted = true;

    const loadFirstGame = async () => {
      setGenerationStatus({ state: 'loading', message: 'Generating live interactive game...' });
      const game = await generateInteractiveGame(currentLearningNode.title, {
        lessonTitle: currentLessonData?.title,
        lessonSnippet: currentLessonData?.content?.mainContent || currentLessonData?.content?.introduction || '',
        difficulty: sessionState.difficulty,
        learningStyle: aiSettings.learningStyle,
        recentPerformance: sessionState.performance || 50,
        strugglingConcepts: aiAnalytics.strugglingConcepts,
        feedbackHistory,
      });

      if (!isMounted) return;

      if (game) {
        setLiveGame(game);
        setSessionState((prev) => ({ ...prev, currentContentType: 'game' }));
        setGenerationStatus({ state: 'ready', message: 'Live game ready.' });
      } else {
        setGenerationStatus({ state: 'idle', message: 'Using curated lessons — AI game unavailable.' });
      }
    };

    loadFirstGame();

    return () => {
      isMounted = false;
    };
  }, [currentLearningNode?.id, aiConfigured]);

  // Optional: personalized module overlay when enabled (secondary to live games)
  useEffect(() => {
    if (!currentLearningNode || !aiSettings.personalizedContent || !aiConfigured) {
      return;
    }

    const cachedModule = loadCachedModule(currentLearningNode.id);
    if (cachedModule) {
      setProceduralModule(cachedModule);
      if (cachedModule.lessons?.length && !availableLessons.length) {
        setAvailableLessons(cachedModule.lessons);
        setCurrentLessonIndex(0);
        setCurrentLessonData(cachedModule.lessons[0]);
      }
    }
  }, [currentLearningNode?.id, aiSettings.personalizedContent, aiConfigured]);

  // Update content when learning node or lesson changes
  useEffect(() => {
    if (currentLearningNode) {
      const nodeContent = generateContentForNode(currentLearningNode, currentLessonData);
      const fallbackQuiz = generateQuizForNode(currentLearningNode, currentLessonData);
      const effectiveQuiz = generatedQuiz || fallbackQuiz;
      setContentData(prev => ({
        ...prev,
        currentLesson: {
          ...nodeContent,
          id: currentLearningNode.id,
          lessonId: currentLessonData?.id,
          lessonOrder: currentLessonData?.order,
          totalLessons: availableLessons.length
        },
        quiz: effectiveQuiz
      }));
    }
  }, [currentLearningNode, currentLessonData, availableLessons, generatedQuiz]);

  useEffect(() => {
    if (!currentLearningNode || !aiSettings.personalizedContent || !aiConfigured) {
      setGeneratedQuiz(null);
      return;
    }

    let isMounted = true;
    const controller = new AbortController();

    const createQuiz = async () => {
      const quizData = await generateAdaptiveQuiz(
        currentLearningNode.title,
        sessionState.difficulty,
        4,
        { signal: controller.signal }
      );

      if (!isMounted) return;

      const normalizedQuiz = normalizeGeneratedQuiz(quizData);
      setGeneratedQuiz(normalizedQuiz);
    };

    createQuiz();

    return () => {
      isMounted = false;
      controller.abort();
    };
  }, [
    currentLearningNode,
    sessionState.difficulty,
    aiSettings.personalizedContent,
    aiSettings.learningStyle,
    adaptiveMetrics.learningRate,
    generateAdaptiveQuiz,
    aiConfigured
  ]);

  // Generate quiz content based on the current learning node and lesson data
  const generateQuizForNode = (node, lessonData = null) => {
    // If we have detailed lesson data with practice problems, use them
    if (lessonData && lessonData.content && lessonData.content.practiceProblems && lessonData.content.practiceProblems.length > 0) {
      const problem = lessonData.content.practiceProblems[0]; // Use first practice problem
      return {
        question: problem.question,
        options: problem.options,
        correctAnswer: Number.isInteger(problem.correct) ? problem.correct : problem.correctAnswer || 0,
        explanation: problem.explanation
      };
    }
    
    // Fallback to original quiz templates if no lesson-specific problems
    if (!node) return getDefaultQuiz();
    
    const quizTemplates = {
      'math-fundamentals': {
        question: "Which of the following best describes the role of mathematics in everyday life?",
        options: [
          "Only useful for advanced scientific calculations",
          "A universal language for solving logical problems",
          "Mainly for academic purposes only",
          "Limited to basic arithmetic operations"
        ],
        correctAnswer: 1,
        explanation: "Mathematics is indeed a universal language that helps us solve logical problems, from basic calculations to complex decision-making in daily life."
      },
      'algebra-intro': {
        question: "What is the primary purpose of using variables (like x and y) in algebra?",
        options: [
          "To make math more complicated",
          "To represent unknown or changing values",
          "To replace all numbers in equations",
          "To confuse students with letters"
        ],
        correctAnswer: 1,
        explanation: "Variables allow us to represent unknown values and solve entire families of problems, making algebra a powerful tool for modeling real-world situations."
      },
      'programming-fundamentals': {
        question: "What is the most important skill that programming develops?",
        options: [
          "Memorizing computer commands",
          "Typing very quickly",
          "Breaking down complex problems into smaller steps",
          "Understanding every programming language"
        ],
        correctAnswer: 2,
        explanation: "Programming teaches algorithmic thinking - the ability to break complex problems into manageable steps, which is valuable in any field."
      },
      'ancient-civilizations': {
        question: "Why is studying ancient civilizations relevant to modern life?",
        options: [
          "To memorize historical dates",
          "To understand how human societies developed solutions to universal problems",
          "Only for academic requirements",
          "To prove which civilization was the best"
        ],
        correctAnswer: 1,
        explanation: "Ancient civilizations developed solutions to problems we still face today - governance, trade, communication, and social organization - providing valuable insights for modern society."
      }
    };

    return quizTemplates[node.id] || getDefaultQuiz();
  };

  const normalizeGeneratedQuiz = (quizData) => {
    if (!quizData) return null;

    const questionSource = Array.isArray(quizData.questions) && quizData.questions.length > 0
      ? quizData.questions[0]
      : quizData.question
        ? quizData
        : null;

    if (!questionSource) return null;

    return {
      question: questionSource.question || 'Check your understanding of this topic.',
      options: Array.isArray(questionSource.options) && questionSource.options.length > 1
        ? questionSource.options
        : ['Option A', 'Option B', 'Option C', 'Option D'],
      correctAnswer: Number.isInteger(questionSource.correct)
        ? questionSource.correct
        : Number.isInteger(questionSource.correctAnswer)
          ? questionSource.correctAnswer
          : 0,
      explanation: questionSource.explanation || 'Review the lesson and try again.'
    };
  };

  const getDefaultQuiz = () => ({
    question: "What's the most important aspect of effective learning?",
    options: [
      "Memorizing as much information as possible",
      "Understanding concepts and applying them",
      "Completing assignments quickly",
      "Avoiding difficult topics"
    ],
    correctAnswer: 1,
    explanation: "Effective learning focuses on understanding concepts deeply and being able to apply them to new situations, rather than just memorizing facts."
  });

  const [uiAdaptations, setUiAdaptations] = useState({
    textSize: 'normal',
    contrast: 'normal',
    reducedMotion: false,
    cognitiveLoad: 'normal',
    backgroundColor: '#FAFAF9',
    accentColor: '#4F46E5'
  });

  // Generate dynamic content based on the current lesson data or fallback to node-based content
  const generateContentForNode = (node, lessonData = null) => {
    // If we have detailed lesson data, use it
    if (lessonData && lessonData.content) {
      return {
        title: lessonData.title,
        content: lessonData.content.mainContent,
        introduction: lessonData.content.introduction,
        keyTakeaways: lessonData.content.keyTakeaways || [],
        visualElements: lessonData.content.visualElements || [],
        interactiveElements: lessonData.content.interactiveElements || []
      };
    }
    
    // Fallback to original content templates if no detailed lesson data
    if (!node) return getDefaultContent();
    
    const contentTemplates = {
      'math-fundamentals': {
        title: 'Mathematics Fundamentals',
        content: `Mathematics is the universal language of logic, patterns, and problem-solving. In this foundational course, you'll master essential concepts that serve as building blocks for all advanced mathematical thinking.

We'll explore number systems, basic operations, and mathematical reasoning. Think of mathematics as a toolkit - each concept you learn gives you a new tool to solve increasingly complex problems.

Key areas we'll cover include:
• Number operations and properties
• Basic algebraic thinking
• Problem-solving strategies
• Mathematical communication

These fundamentals appear everywhere: from calculating tips and managing budgets to understanding scientific data and making informed decisions.`,
        visualElements: [
          { type: 'number-line', data: 'interactive-number-operations' },
          { type: 'pattern-explorer', data: 'mathematical-sequences' }
        ],
        interactiveElements: [
          { type: 'calculator', label: 'Practice basic operations', action: 'solve-problems' },
          { type: 'pattern-game', label: 'Find the next number', action: 'sequence-completion' }
        ]
      },
      'algebra-intro': {
        title: 'Introduction to Algebra',
        content: `Algebra is the gateway to higher mathematics, introducing the powerful concept of variables - letters that represent unknown numbers. This abstraction allows us to solve entire families of problems at once.

Think of algebra as learning a new language where x, y, and z aren't just letters, but placeholders for any number. Once you master this language, you can solve real-world problems like calculating loan payments, optimizing business costs, or predicting growth patterns.

In this module, you'll learn:
• Variables and expressions
• Solving linear equations
• Graphing relationships
• Word problem strategies

Algebra bridges the gap between arithmetic and advanced mathematics, giving you tools to model and solve complex situations.`,
        visualElements: [
          { type: 'balance-scale', data: 'equation-solving' },
          { type: 'graph', data: 'linear-relationships' }
        ],
        interactiveElements: [
          { type: 'equation-solver', label: 'Balance the equation', action: 'solve-linear' },
          { type: 'variable-slider', label: 'See how variables change graphs', action: 'dynamic-graphing' }
        ]
      },
      'programming-fundamentals': {
        title: 'Programming Fundamentals',
        content: `Programming is the art of giving precise instructions to computers to solve problems and automate tasks. Learning to code develops logical thinking, problem decomposition, and systematic approach to challenges.

Every app, website, and digital tool you use was created through programming. By learning these fundamentals, you're gaining a superpower in our digital world - the ability to create, not just consume technology.

Core concepts we'll explore:
• Algorithms and logical thinking
• Variables and data types
• Control structures (loops, conditions)
• Functions and code organization
• Debugging and problem-solving

Programming isn't just about computers - it teaches you to think systematically about any complex problem.`,
        visualElements: [
          { type: 'flowchart', data: 'algorithm-visualization' },
          { type: 'code-editor', data: 'live-coding-environment' }
        ],
        interactiveElements: [
          { type: 'code-blocks', label: 'Drag blocks to create programs', action: 'visual-programming' },
          { type: 'debugging-game', label: 'Find and fix the bugs', action: 'debug-challenge' }
        ]
      },
      'ancient-civilizations': {
        title: 'Ancient Civilizations',
        content: `Journey back in time to explore the fascinating world of ancient civilizations - the foundations of human society, culture, and innovation. These early societies developed writing, laws, architecture, and ideas that still influence our world today.

From the pyramids of Egypt to the philosophy of Greece, from the engineering marvels of Rome to the innovations of ancient China, you'll discover how our ancestors solved problems, organized societies, and created lasting legacies.

Key civilizations we'll explore:
• Mesopotamia - The cradle of civilization
• Ancient Egypt - Masters of engineering and art
• Ancient Greece - Birthplace of democracy and philosophy
• Roman Empire - Law, engineering, and administration
• Ancient China - Innovation and cultural achievements

Understanding these civilizations helps us appreciate human ingenuity and see patterns that still shape our modern world.`,
        visualElements: [
          { type: 'timeline', data: 'civilization-chronology' },
          { type: 'interactive-map', data: 'ancient-world-geography' }
        ],
        interactiveElements: [
          { type: 'artifact-explorer', label: 'Examine ancient artifacts', action: 'archaeological-analysis' },
          { type: 'civilization-builder', label: 'Build your own ancient city', action: 'city-planning-simulation' }
        ]
      }
    };

    return contentTemplates[node.id] || getDefaultContent();
  };

  const getDefaultContent = () => ({
    title: 'Learning Session',
    content: `Welcome to your adaptive learning session! This interactive environment adjusts to your learning style and pace.

Each session is designed to build upon your existing knowledge while introducing new concepts in an engaging, personalized way. You'll encounter various types of content including visual explanations, interactive exercises, and real-world applications.

Take your time to explore, ask questions, and practice. The AI system monitors your progress and adjusts the difficulty to keep you in the optimal learning zone - challenging enough to grow, but not so difficult as to be overwhelming.`,
    visualElements: [
      { type: 'learning-path', data: 'personalized-journey' }
    ],
    interactiveElements: [
      { type: 'learning-style-quiz', label: 'Discover your learning preferences', action: 'personalization-setup' }
    ]
  });

  const [contentData, setContentData] = useState(() => {
    const defaultContent = getDefaultContent();
    return {
      currentLesson: defaultContent,
      quiz: {
        question: "What does the derivative of a position function represent?",
        options: [
          "Acceleration",
          "Velocity", 
          "Distance",
          "Time"
        ],
        correctAnswer: 1,
        explanation: "The derivative of position with respect to time gives us velocity - the rate of change of position."
      },
      arContent: {
        model: '3d-function-surface',
        interactions: ['rotate', 'zoom', 'cross-section'],
        overlayInfo: 'Explore how derivatives change across the surface'
      }
    };
  });
  const [generatedQuiz, setGeneratedQuiz] = useState(null);
  const [liveGame, setLiveGame] = useState(null);
  const [coachMessage, setCoachMessage] = useState('');
  const [feedbackHistory, setFeedbackHistory] = useState([]);
  const [isAdapting, setIsAdapting] = useState(false);

  const [aiAnalytics, setAiAnalytics] = useState({
    engagementLevel: 'medium',
    comprehensionRate: 0,
    strugglingConcepts: [],
    recommendedActions: [],
    moodInference: 'neutral',
    adaptationTriggers: [],
  });

  const [showHints, setShowHints] = useState(false);
  const [showNotes, setShowNotes] = useState(false);
  const [notes, setNotes] = useState([]);
  const sessionRef = useRef(null);

  // AI-driven interface adaptation
  useEffect(() => {
    const adaptInterface = () => {
      const newAdaptations = { ...uiAdaptations };
      
      // Performance-based color adaptation
      if (sessionState.performance > 80) {
        newAdaptations.backgroundColor = '#F0FDF4'; // Success green tint
        newAdaptations.accentColor = '#10B981';
      } else if (sessionState.performance < 60) {
        newAdaptations.backgroundColor = '#FEF2F2'; // Warning red tint
        newAdaptations.accentColor = '#EF4444';
      }

      // Engagement-based adaptations
      if (aiAnalytics.engagementLevel === 'low') {
        newAdaptations.cognitiveLoad = 'reduced';
      }

      // Mood-based adaptations
      if (aiAnalytics.moodInference === 'frustrated') {
        newAdaptations.textSize = 'large';
        newAdaptations.contrast = 'high';
      }

      setUiAdaptations(newAdaptations);
    };

    const interval = setInterval(adaptInterface, 5000);
    return () => clearInterval(interval);
  }, [sessionState.performance, aiAnalytics]);

  // Session timer
  useEffect(() => {
    let timer;
    if (sessionState.isActive) {
      timer = setInterval(() => {
        setSessionState(prev => ({
          ...prev,
          sessionDuration: prev.sessionDuration + 1
        }));
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [sessionState.isActive]);

  const handleContentTypeChange = (newType) => {
    setSessionState(prev => ({
      ...prev,
      currentContentType: newType
    }));
  };

  const handlePerformanceUpdate = (payload, progressIncrement = 5) => {
    const data = typeof payload === 'object' ? payload : { performance: payload };
    const newPerformance = data.performance ?? 0;

    setSessionState((prev) => {
      const updatedProgress = Math.min(prev.progress + progressIncrement, 100);
      const isCompleted = updatedProgress >= 100;

      if (currentLearningNode) {
        updateNodeProgress(currentLearningNode.id, updatedProgress, isCompleted);
      }

      return {
        ...prev,
        performance: newPerformance,
        progress: updatedProgress,
      };
    });

    const adaptation = adaptLearning({
      accuracy: newPerformance / 100,
      timeSpent: sessionState.sessionDuration / 60,
      strugglingTopics: newPerformance < 60 && currentLearningNode ? [currentLearningNode.title] : [],
      masteredTopics: newPerformance >= 80 && currentLearningNode ? [currentLearningNode.title] : [],
    });

    if (adaptation) {
      setAiAnalytics((prev) => ({
        ...prev,
        recommendedActions: [
          ...adaptation.recommendedContentTypes.map((type) => `Try more ${type.replace(/-/g, ' ')}`),
          `Suggested break: ${adaptation.suggestedBreakTime} minutes`,
        ].slice(0, 3),
      }));
    }

    if (aiConfigured && currentLearningNode && (data.correct !== undefined || data.score !== undefined)) {
      applyMidSessionSignals({
        performance: newPerformance,
        confidence: data.confidence,
        quizCorrect: data.correct,
        gameScore: data.score,
        feedbackComment: data.feedbackComment,
      });
    }
  };

  const applyMidSessionSignals = async (signals = {}) => {
    if (!currentLearningNode || !aiConfigured || isAdapting) return;

    setIsAdapting(true);
    try {
      const adaptation = await adaptMidSession(currentLearningNode.title, {
        lessonTitle: currentLessonData?.title,
        performance: signals.performance ?? sessionState.performance,
        confidence: signals.confidence,
        difficultyRating: signals.difficultyRating,
        sentiment: signals.sentiment,
        quizCorrect: signals.quizCorrect,
        gameScore: signals.gameScore,
        timeSpentSeconds: sessionState.sessionDuration,
        strugglingConcepts: aiAnalytics.strugglingConcepts,
        feedbackComment: signals.feedbackComment || '',
        currentDifficulty: sessionState.difficulty,
      });

      if (!adaptation) return;

      setCoachMessage(adaptation.coachMessage);
      setAiAnalytics((prev) => ({
        ...prev,
        engagementLevel:
          adaptation.uiAdaptations?.accentTone === 'celebratory'
            ? 'high'
            : adaptation.uiAdaptations?.cognitiveLoad === 'reduced'
              ? 'low'
              : prev.engagementLevel,
        moodInference:
          signals.sentiment <= 2 ? 'frustrated' : signals.sentiment >= 4 ? 'engaged' : prev.moodInference,
        strugglingConcepts: adaptation.focusAreas?.length ? adaptation.focusAreas : prev.strugglingConcepts,
        recommendedActions: adaptation.recommendedActions?.length
          ? adaptation.recommendedActions
          : prev.recommendedActions,
      }));

      if (adaptation.newDifficulty) {
        setSessionState((prev) => ({ ...prev, difficulty: adaptation.newDifficulty }));
      }

      if (adaptation.uiAdaptations) {
        setUiAdaptations((prev) => ({
          ...prev,
          textSize: adaptation.uiAdaptations.textSize === 'large' ? 'large' : prev.textSize,
          cognitiveLoad: adaptation.uiAdaptations.cognitiveLoad || prev.cognitiveLoad,
        }));
      }

      if (adaptation.shouldGenerateGame && adaptation.recommendedContentType === 'game') {
        const game = await generateInteractiveGame(currentLearningNode.title, {
          lessonTitle: currentLessonData?.title,
          lessonSnippet: adaptation.gameTheme,
          difficulty: adaptation.newDifficulty || sessionState.difficulty,
          learningStyle: aiSettings.learningStyle,
          recentPerformance: signals.performance ?? sessionState.performance,
          strugglingConcepts: adaptation.focusAreas,
          feedbackHistory,
          gameType: 'auto',
        });
        if (game) {
          setLiveGame(game);
          setSessionState((prev) => ({ ...prev, currentContentType: 'game' }));
        }
      } else if (adaptation.recommendedContentType === 'quiz') {
        setSessionState((prev) => ({ ...prev, currentContentType: 'quiz' }));
      }
    } finally {
      setIsAdapting(false);
    }
  };

  const handleFeedbackSubmit = async (feedback) => {
    setFeedbackHistory((prev) => [...prev, feedback]);
    await applyMidSessionSignals({
      sentiment: feedback.sentiment,
      difficultyRating: feedback.difficultyRating,
      feedbackComment: feedback.comment,
      performance: sessionState.performance,
    });
  };

  const handleGameComplete = ({ score }) => {
    handlePerformanceUpdate({ performance: score, score }, 8);
  };

  const requestNewGame = async () => {
    if (!currentLearningNode || !aiConfigured) return;
    setGenerationStatus({ state: 'loading', message: 'Generating new game...' });
    const game = await generateInteractiveGame(currentLearningNode.title, {
      lessonTitle: currentLessonData?.title,
      lessonSnippet: currentLessonData?.content?.mainContent?.slice(0, 300) || '',
      difficulty: sessionState.difficulty,
      learningStyle: aiSettings.learningStyle,
      recentPerformance: sessionState.performance,
      strugglingConcepts: aiAnalytics.strugglingConcepts,
      feedbackHistory,
    });
    if (game) {
      setLiveGame(game);
      setSessionState((prev) => ({ ...prev, currentContentType: 'game' }));
      setGenerationStatus({ state: 'ready', message: 'New game ready.' });
    } else {
      setGenerationStatus({ state: 'error', message: 'Could not generate game.' });
    }
  };

  // Example function to explicitly mark a lesson as complete or set specific progress
  const markLessonProgress = (newProgressPercentage) => {
    if (currentLearningNode) {
      const isCompleted = newProgressPercentage >= 100;
      setSessionState(prev => ({
        ...prev,
        progress: newProgressPercentage,
      }));
      updateNodeProgress(currentLearningNode.id, newProgressPercentage, isCompleted);

      if (isCompleted) {
        console.log(`Lesson "${currentLearningNode.title}" marked as complete.`);
        // Optionally, navigate away or show a completion message
        // navigate('/adaptive-learning-dashboard');
      }
    }
  };

  // Example: Call this when user clicks a "Complete Lesson" button or finishes all parts
  const handleCompleteLesson = () => {
    markLessonProgress(100);
  };

  // Lesson navigation functions
  const goToNextLesson = () => {
    if (currentLessonIndex < availableLessons.length - 1) {
      const nextIndex = currentLessonIndex + 1;
      setCurrentLessonIndex(nextIndex);
      setCurrentLessonData(availableLessons[nextIndex]);
    }
  };

  const goToPreviousLesson = () => {
    if (currentLessonIndex > 0) {
      const prevIndex = currentLessonIndex - 1;
      setCurrentLessonIndex(prevIndex);
      setCurrentLessonData(availableLessons[prevIndex]);
    }
  };

  const goToSpecificLesson = (lessonIndex) => {
    if (lessonIndex >= 0 && lessonIndex < availableLessons.length) {
      setCurrentLessonIndex(lessonIndex);
      setCurrentLessonData(availableLessons[lessonIndex]);
    }
  };

  const markCurrentLessonComplete = () => {
    if (currentLessonData && availableLessons.length > 0) {
      // Calculate progress based on lessons completed
      const lessonsCompleted = currentLessonIndex + 1;
      const progressPercentage = Math.round((lessonsCompleted / availableLessons.length) * 100);
      markLessonProgress(progressPercentage);
      
      // Auto-advance to next lesson if not the last one
      if (currentLessonIndex < availableLessons.length - 1) {
        setTimeout(() => {
          goToNextLesson();
        }, 1000); // Brief delay to show completion
      }
    } else {
      // Fallback to old behavior
      handleCompleteLesson();
    }
  };


  const handleSessionEnd = async () => {
    if (currentLearningNode) {
      try {
        const result = await api.completeSession({
          nodeId: currentLearningNode.id,
          topic: currentLearningNode.title,
          durationSeconds: sessionState.sessionDuration,
          progress: sessionState.progress,
          performance: sessionState.performance,
          lessonCount: availableLessons.length,
          lessonsCompleted: availableLessons.length ? currentLessonIndex + 1 : 0,
          contentSource: proceduralModule ? 'procedural' : 'curated',
        });

        if (result?.adaptation) {
          setAiAnalytics((prev) => ({
            ...prev,
            engagementLevel: result.adaptation.engagementLevel,
            comprehensionRate: result.adaptation.comprehensionRate,
            strugglingConcepts: result.adaptation.weaknesses || [],
            recommendedActions: result.adaptation.recommendedActions || prev.recommendedActions,
            moodInference: result.adaptation.moodInference,
          }));
        }

        await Promise.all([refreshProgress?.(), refreshData?.()]);
      } catch (err) {
        console.error('Failed to save session:', err);
        recordLearningSession({
          nodeId: currentLearningNode.id,
          topic: currentLearningNode.title,
          durationSeconds: sessionState.sessionDuration,
          progress: sessionState.progress,
          performance: sessionState.performance,
        });
      }
    }

    setSessionState((prev) => ({ ...prev, isActive: false }));
    navigate('/adaptive-learning-dashboard');
  };

  const addNote = (noteContent) => {
    const newNote = {
      id: Date.now(),
      content: noteContent,
      timestamp: new Date(),
      topic: sessionState.currentTopic
    };
    setNotes(prev => [...prev, newNote]);
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div 
      className="min-h-screen transition-colors duration-1000"
      style={{ backgroundColor: uiAdaptations.backgroundColor }}
      ref={sessionRef}
    >
      {/* Session Header */}
      <SessionHeader
        sessionState={sessionState}
        onSessionEnd={handleSessionEnd}
        formatTime={formatTime}
        uiAdaptations={uiAdaptations}
      />

      {/* Main Content Area */}
      <div className="px-4 py-6 lg:px-6 max-w-7xl mx-auto pb-20 lg:pb-6">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          {/* Primary Content */}
          <div className="lg:col-span-8">
            <div className="bg-surface rounded-xl border border-border shadow-warm-md overflow-hidden">
              {/* Content Type Indicator */}
              <div className="bg-surface-50 px-6 py-3 border-b border-border">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <div 
                      className="w-3 h-3 rounded-full animate-pulse"
                      style={{ backgroundColor: uiAdaptations.accentColor }}
                    ></div>
                    <div className="flex flex-col">
                      <span className="text-sm font-medium text-text-primary">
                        {sessionState.currentContentType === 'lesson' && (
                          currentLessonData ? `${currentLessonData.title}` : 'Interactive Lesson'
                        )}
                        {sessionState.currentContentType === 'quiz' && 'Knowledge Check'}
                        {sessionState.currentContentType === 'game' && 'Live AI Game'}
                        {sessionState.currentContentType === 'ar' && 'AR Exploration'}
                        {sessionState.currentContentType === 'exercise' && 'Practice Exercise'}
                      </span>
                      {availableLessons.length > 1 && (
                        <span className="text-xs text-text-secondary">
                          Lesson {currentLessonIndex + 1} of {availableLessons.length} • {currentLessonData?.duration || '30 min'}
                        </span>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center space-x-2">
                    <span className="text-xs text-text-secondary">
                      Difficulty: {sessionState.difficulty}
                    </span>
                    <div className="w-px h-4 bg-border"></div>
                    <span className="text-xs text-text-secondary">
                      Style: {sessionState.learningStyle}
                    </span>
                    {currentLessonData?.type && (
                      <>
                        <div className="w-px h-4 bg-border"></div>
                        <span className="text-xs text-text-secondary capitalize">
                          {currentLessonData.type}
                        </span>
                      </>
                    )}
                  </div>
                </div>
              </div>

              {/* Dynamic Content Renderer */}
              <div className="p-6">
                {generationStatus.state === 'loading' && (
                  <div className="mb-4 flex items-center gap-2 text-sm text-primary">
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-primary" />
                    {generationStatus.message}
                  </div>
                )}

                {sessionState.currentContentType === 'lesson' && (
                  <ContentRenderer
                    content={contentData.currentLesson}
                    uiAdaptations={uiAdaptations}
                    onInteraction={(perf) => handlePerformanceUpdate(perf, 3)}
                  />
                )}

                {sessionState.currentContentType === 'game' && (
                  <LiveInteractiveGame
                    game={liveGame}
                    uiAdaptations={uiAdaptations}
                    onComplete={handleGameComplete}
                    onAbandon={() => handleContentTypeChange('lesson')}
                  />
                )}

                {sessionState.currentContentType === 'quiz' && (
                  <InteractiveQuiz
                    quiz={contentData.quiz}
                    uiAdaptations={uiAdaptations}
                    onAnswer={(result) =>
                      handlePerformanceUpdate(
                        {
                          performance: result.performance,
                          correct: result.correct,
                          confidence: result.confidence,
                        },
                        6
                      )
                    }
                  />
                )}

                {sessionState.currentContentType === 'ar' && (
                  <ARInterface
                    arContent={contentData.arContent}
                    uiAdaptations={uiAdaptations}
                    onInteraction={(perf) => handlePerformanceUpdate(perf, 3)}
                  />
                )}
              </div>
            </div>

            {/* Content Navigation */}
            <div className="mt-6 space-y-4">
              {/* Lesson Progress and Navigation */}
              {availableLessons.length > 1 && (
                <div className="bg-surface rounded-lg border border-border p-4">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="font-heading font-semibold text-text-primary">
                      Lesson {currentLessonIndex + 1} of {availableLessons.length}
                    </h3>
                    <span className="text-sm text-text-secondary">
                      {currentLessonData?.duration || '30 min'}
                    </span>
                  </div>
                  
                  <div className="mb-3">
                    <div className="w-full bg-surface-200 rounded-full h-2">
                      <div 
                        className="bg-primary h-2 rounded-full transition-all duration-300"
                        style={{ width: `${((currentLessonIndex + 1) / availableLessons.length) * 100}%` }}
                      ></div>
                    </div>
                  </div>
                  
                  <div className="flex items-center justify-between">
                    <button 
                      onClick={goToPreviousLesson}
                      disabled={currentLessonIndex === 0}
                      className="btn btn-outline px-4 py-2 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      <Icon name="ChevronLeft" size={16} className="mr-2" />
                      Previous Lesson
                    </button>
                    
                    <div className="flex space-x-1">
                      {availableLessons.map((_, index) => (
                        <button
                          key={index}
                          onClick={() => goToSpecificLesson(index)}
                          className={`w-8 h-8 rounded-full text-xs font-medium transition-all duration-200 ${
                            index === currentLessonIndex 
                              ? 'bg-primary text-white' 
                              : index < currentLessonIndex 
                                ? 'bg-success text-white' 
                                : 'bg-surface-100 text-text-secondary hover:bg-surface-200'
                          }`}
                        >
                          {index + 1}
                        </button>
                      ))}
                    </div>
                    
                    <button 
                      onClick={goToNextLesson}
                      disabled={currentLessonIndex === availableLessons.length - 1}
                      className="btn btn-outline px-4 py-2 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      Next Lesson
                      <Icon name="ChevronRight" size={16} className="ml-2" />
                    </button>
                  </div>
                </div>
              )}
              
              {/* Content Type and Action Navigation */}
              <div className="flex items-center justify-between">
                <button 
                  onClick={() => navigate('/adaptive-learning-dashboard')}
                  className="btn btn-outline px-6 py-3"
                >
                  <Icon name="ChevronLeft" size={16} className="mr-2" />
                  Back to Dashboard
                </button>

                <div className="flex space-x-2">
                  <button
                    onClick={() => handleContentTypeChange('lesson')}
                    className={`p-3 rounded-lg transition-all duration-200 ${
                      sessionState.currentContentType === 'lesson' ?'bg-primary text-white' :'bg-surface-50 text-text-secondary hover:bg-surface-100'
                    }`}
                  >
                    <Icon name="BookOpen" size={16} />
                  </button>
                  <button
                    onClick={() => handleContentTypeChange('game')}
                    className={`p-3 rounded-lg transition-all duration-200 ${
                      sessionState.currentContentType === 'game' ?'bg-primary text-white' :'bg-surface-50 text-text-secondary hover:bg-surface-100'
                    }`}
                    title="Live AI Game"
                  >
                    <Icon name="Gamepad2" size={16} />
                  </button>
                  <button
                    onClick={() => handleContentTypeChange('quiz')}
                    className={`p-3 rounded-lg transition-all duration-200 ${
                      sessionState.currentContentType === 'quiz' ?'bg-primary text-white' :'bg-surface-50 text-text-secondary hover:bg-surface-100'
                    }`}
                  >
                    <Icon name="HelpCircle" size={16} />
                  </button>
                  <button
                    onClick={() => handleContentTypeChange('ar')}
                    className={`p-3 rounded-lg transition-all duration-200 ${
                      sessionState.currentContentType === 'ar' ?'bg-primary text-white' :'bg-surface-50 text-text-secondary hover:bg-surface-100'
                    }`}
                  >
                    <Icon name="Glasses" size={16} />
                  </button>
                </div>

                <button 
                  className="btn btn-primary px-6 py-3" 
                  onClick={markCurrentLessonComplete}
                >
                  {availableLessons.length > 1 
                    ? (currentLessonIndex === availableLessons.length - 1 ? 'Complete Module' : 'Complete Lesson')
                    : 'Mark as Complete'
                  }
                  <Icon name="CheckCircle" size={16} className="ml-2" />
                </button>
              </div>
            </div>
          </div>

          {/* Secondary Content Panel - Desktop Only */}
          <div className="hidden lg:block lg:col-span-4">
            <div className="space-y-6 sticky top-24">
              {/* Live feedback + AI coach */}
              <SessionFeedbackPanel
                onSubmit={handleFeedbackSubmit}
                disabled={isAdapting || isGenerating}
                coachMessage={coachMessage}
                uiAdaptations={uiAdaptations}
              />

              {/* Progress Indicator */}
              <ProgressIndicator
                progress={sessionState.progress}
                performance={sessionState.performance}
                uiAdaptations={uiAdaptations}
              />

              {/* AI Insights */}
              <div className="bg-surface rounded-xl border border-border shadow-warm-md p-6">
                <div className="flex items-center space-x-3 mb-4">
                  <div 
                    className="p-2 rounded-lg"
                    style={{ backgroundColor: `${uiAdaptations.accentColor}20` }}
                  >
                    <Icon 
                      name="Brain" 
                      size={16} 
                      style={{ color: uiAdaptations.accentColor }}
                    />
                  </div>
                  <h3 className="font-heading font-semibold text-text-primary">
                    AI Insights
                  </h3>
                </div>

                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-text-secondary">Engagement</span>
                    <span className="text-sm font-medium text-text-primary capitalize">
                      {aiAnalytics.engagementLevel}
                    </span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-text-secondary">Comprehension</span>
                    <span className="text-sm font-medium text-text-primary">
                      {Math.round(aiAnalytics.comprehensionRate * 100)}%
                    </span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-text-secondary">Mood</span>
                    <span className="text-sm font-medium text-text-primary capitalize">
                      {aiAnalytics.moodInference}
                    </span>
                  </div>
                </div>

                {aiAnalytics.recommendedActions.length > 0 && (
                  <div className="mt-4 pt-4 border-t border-border">
                    <h4 className="text-sm font-medium text-text-primary mb-2">
                      Recommendations
                    </h4>
                    <div className="space-y-2">
                      {aiAnalytics.recommendedActions.map((action, index) => (
                        <div key={index} className="flex items-center space-x-2">
                          <div className="w-1.5 h-1.5 bg-primary rounded-full"></div>
                          <span className="text-xs text-text-secondary">{action}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* Quick Actions */}
              <div className="bg-surface rounded-xl border border-border shadow-warm-md p-6">
                <h3 className="font-heading font-semibold text-text-primary mb-4">
                  Quick Actions
                </h3>
                <div className="space-y-3">
                  <button
                    onClick={requestNewGame}
                    disabled={!aiConfigured || isGenerating}
                    className="w-full flex items-center space-x-3 p-3 bg-surface-50 rounded-lg hover:bg-surface-100 transition-colors duration-200 disabled:opacity-50"
                  >
                    <Icon name="Gamepad2" size={16} className="text-primary" />
                    <span className="text-sm font-medium text-text-primary">
                      {isGenerating ? 'Generating game...' : 'New AI Game'}
                    </span>
                  </button>
                  <button
                    onClick={() => setShowHints(!showHints)}
                    className="w-full flex items-center space-x-3 p-3 bg-surface-50 rounded-lg hover:bg-surface-100 transition-colors duration-200"
                  >
                    <Icon name="Lightbulb" size={16} className="text-accent" />
                    <span className="text-sm font-medium text-text-primary">
                      Get Hints
                    </span>
                  </button>
                  <button
                    onClick={() => setShowNotes(!showNotes)}
                    className="w-full flex items-center space-x-3 p-3 bg-surface-50 rounded-lg hover:bg-surface-100 transition-colors duration-200"
                  >
                    <Icon name="PenTool" size={16} className="text-secondary" />
                    <span className="text-sm font-medium text-text-primary">
                      Take Notes
                    </span>
                  </button>
                  <Link
                    to="/progress-analytics-dashboard"
                    className="w-full flex items-center space-x-3 p-3 bg-surface-50 rounded-lg hover:bg-surface-100 transition-colors duration-200"
                  >
                    <Icon name="BarChart3" size={16} className="text-primary" />
                    <span className="text-sm font-medium text-text-primary">
                      View Analytics
                    </span>
                  </Link>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Bottom Navigation - Mobile */}
      <div className="lg:hidden fixed bottom-0 left-0 right-0 bg-surface border-t border-border shadow-warm-lg">
        <div className="flex items-center justify-around py-3">
          <button
            onClick={() => setShowHints(!showHints)}
            className="flex flex-col items-center space-y-1 p-2"
          >
            <Icon name="Lightbulb" size={20} className="text-accent" />
            <span className="text-xs text-text-secondary">Hints</span>
          </button>
          <button
            onClick={() => setShowNotes(!showNotes)}
            className="flex flex-col items-center space-y-1 p-2"
          >
            <Icon name="PenTool" size={20} className="text-secondary" />
            <span className="text-xs text-text-secondary">Notes</span>
          </button>
          <div className="flex flex-col items-center space-y-1 p-2">
            <div className="text-lg font-heading font-semibold text-text-primary">
              {sessionState.progress}%
            </div>
            <span className="text-xs text-text-secondary">Progress</span>
          </div>
          <Link
            to="/progress-analytics-dashboard"
            className="flex flex-col items-center space-y-1 p-2"
          >
            <Icon name="BarChart3" size={20} className="text-primary" />
            <span className="text-xs text-text-secondary">Analytics</span>
          </Link>
        </div>
      </div>

      {/* Overlay Components */}
      {showHints && (
        <HintSystem
          currentTopic={sessionState.currentTopic}
          strugglingConcepts={aiAnalytics.strugglingConcepts}
          onClose={() => setShowHints(false)}
          uiAdaptations={uiAdaptations}
        />
      )}

      {showNotes && (
        <NoteTaking
          notes={notes}
          onAddNote={addNote}
          onClose={() => setShowNotes(false)}
          uiAdaptations={uiAdaptations}
        />
      )}

      {/* Accessibility Announcements */}
      <div className="sr-only" aria-live="polite" aria-atomic="true">
        {sessionState.currentContentType === 'lesson' && 'Interactive lesson content loaded'}
        {sessionState.currentContentType === 'quiz' && 'Quiz question ready for interaction'}
        {sessionState.currentContentType === 'ar' && 'AR interface activated'}
        {generationStatus.message}
      </div>
    </div>
  );
};

export default InteractiveLearningSession;
