import React, { useState, useEffect } from 'react';
import Icon from 'components/AppIcon';

const HintSystem = ({ currentTopic, strugglingConcepts, onClose, uiAdaptations }) => {
  const [currentHintLevel, setCurrentHintLevel] = useState(0);
  const [usedHints, setUsedHints] = useState([]);
  const [aiGeneratedHints, setAiGeneratedHints] = useState([]);

  const hints = [
    {
      level: 1,
      type: 'conceptual',
      title: 'Think About Real-World Examples',
      content: `Consider how speed changes when you're driving. When you press the gas pedal, your speed increases - that rate of change is like a derivative.

The derivative tells us how fast something is changing at any given moment, just like your speedometer shows your instantaneous speed.`,
      icon: 'Car'
    },
    {
      level: 2,
      type: 'visual',title: 'Visualize the Slope',content: `Look at the curve on the graph. The derivative at any point is the slope of the tangent line at that point.If the curve is going up steeply, the derivative is large and positive. If it's going down, the derivative is negative.`,
      icon: 'TrendingUp'
    },
    {
      level: 3,
      type: 'mathematical',
      title: 'Mathematical Definition',
      content: `The derivative f'(x) = lim(h→0) [f(x+h) - f(x)] / h

This limit represents the instantaneous rate of change. As h gets smaller and smaller, we get closer to the exact slope at point x.`,
      icon: 'Calculator'
    },
    {
      level: 4,
      type: 'step-by-step',title: 'Step-by-Step Approach',
      content: `1. Identify the function f(x)
2. Apply the limit definition or use derivative rules
3. Simplify the expression
4. Interpret the result in context

For polynomial functions, use the power rule: d/dx[x^n] = nx^(n-1)`,
      icon: 'List'
    }
  ];

  useEffect(() => {
    // Generate AI-powered hints based on struggling concepts
    const generateAIHints = () => {
      const aiHints = strugglingConcepts.map((concept, index) => ({
        level: hints.length + index + 1,
        type: 'ai-generated',
        title: `Struggling with ${concept}?`,
        content: `Based on your learning pattern, here's a personalized approach to understand ${concept}:

Try breaking it down into smaller steps and practice with simpler examples first. The AI has noticed you learn better with visual representations, so focus on the graphical interpretation.`,
        icon: 'Brain',
        isAI: true
      }));
      setAiGeneratedHints(aiHints);
    };

    if (strugglingConcepts.length > 0) {
      generateAIHints();
    }
  }, [strugglingConcepts]);

  const allHints = [...hints, ...aiGeneratedHints];

  const handleHintRequest = (hintIndex) => {
    if (!usedHints.includes(hintIndex)) {
      setUsedHints(prev => [...prev, hintIndex]);
      setCurrentHintLevel(hintIndex);
    }
  };

  const getTextSize = () => {
    switch (uiAdaptations.textSize) {
      case 'large':
        return 'text-lg leading-relaxed';
      case 'small':
        return 'text-sm leading-normal';
      default:
        return 'text-base leading-relaxed';
    }
  };

  const getContrastClass = () => {
    return uiAdaptations.contrast === 'high' ?'text-gray-900' :'text-text-primary';
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black bg-opacity-50">
      <div className="bg-surface rounded-xl border border-border shadow-warm-xl max-w-2xl w-full max-h-[90vh] overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-border">
          <div className="flex items-center space-x-3">
            <div 
              className="p-2 rounded-lg"
              style={{ backgroundColor: `${uiAdaptations.accentColor}20` }}
            >
              <Icon 
                name="Lightbulb" 
                size={20} 
                style={{ color: uiAdaptations.accentColor }}
              />
            </div>
            <div>
              <h2 className={`font-heading font-bold ${getContrastClass()} ${
                uiAdaptations.textSize === 'large' ? 'text-xl' : 'text-lg'
              }`}>
                Learning Hints
              </h2>
              <p className="text-sm text-text-secondary">
                {currentTopic}
              </p>
            </div>
          </div>
          
          <button
            onClick={onClose}
            className="p-2 text-text-secondary hover:text-text-primary hover:bg-surface-50 rounded-lg transition-colors duration-200"
          >
            <Icon name="X" size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 overflow-y-auto max-h-[calc(90vh-120px)]">
          {/* Hint Level Selector */}
          <div className="mb-6">
            <h3 className={`font-heading font-semibold ${getContrastClass()} mb-3 ${
              uiAdaptations.textSize === 'large' ? 'text-lg' : 'text-base'
            }`}>
              Choose Your Hint Level
            </h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {allHints.map((hint, index) => (
                <button
                  key={index}
                  onClick={() => handleHintRequest(index)}
                  disabled={usedHints.includes(index) && currentHintLevel !== index}
                  className={`p-3 rounded-lg border-2 transition-all duration-200 text-left ${
                    currentHintLevel === index
                      ? hint.isAI
                        ? 'border-primary bg-primary-50 text-primary-700' :'border-accent bg-accent-50 text-accent-700'
                      : usedHints.includes(index)
                        ? 'border-success bg-success-50 text-success-700' :'border-border bg-surface hover:bg-surface-50 text-text-primary'
                  } ${usedHints.includes(index) && currentHintLevel !== index ? 'opacity-60' : ''}`}
                >
                  <div className="flex items-center space-x-2 mb-1">
                    <Icon 
                      name={hint.icon} 
                      size={16} 
                      className={
                        currentHintLevel === index
                          ? hint.isAI ? 'text-primary' : 'text-accent'
                          : usedHints.includes(index)
                            ? 'text-success' :'text-text-secondary'
                      }
                    />
                    {hint.isAI && (
                      <div className="w-2 h-2 bg-primary rounded-full animate-pulse"></div>
                    )}
                  </div>
                  <div className="text-xs font-medium">
                    Level {hint.level}
                  </div>
                  <div className="text-xs text-text-secondary capitalize">
                    {hint.type.replace('-', ' ')}
                  </div>
                  {usedHints.includes(index) && (
                    <Icon name="Check" size={12} className="text-success mt-1" />
                  )}
                </button>
              ))}
            </div>
          </div>

          {/* Current Hint Display */}
          {currentHintLevel !== null && allHints[currentHintLevel] && (
            <div className={`p-6 rounded-lg border-2 ${
              allHints[currentHintLevel].isAI
                ? 'border-primary bg-primary-50' :'border-accent bg-accent-50'
            }`}>
              <div className="flex items-start space-x-3">
                <div className={`p-2 rounded-lg ${
                  allHints[currentHintLevel].isAI
                    ? 'bg-primary text-white' :'bg-accent text-white'
                }`}>
                  <Icon name={allHints[currentHintLevel].icon} size={20} />
                </div>
                <div className="flex-1">
                  <h4 className={`font-heading font-semibold mb-3 ${
                    allHints[currentHintLevel].isAI ? 'text-primary-700' : 'text-accent-700'
                  } ${uiAdaptations.textSize === 'large' ? 'text-lg' : 'text-base'}`}>
                    {allHints[currentHintLevel].title}
                  </h4>
                  <div className={`${getTextSize()} ${
                    allHints[currentHintLevel].isAI ? 'text-primary-600' : 'text-accent-600'
                  }`}>
                    {allHints[currentHintLevel].content.split('\n\n').map((paragraph, index) => (
                      <p key={index} className="mb-3 last:mb-0">
                        {paragraph}
                      </p>
                    ))}
                  </div>
                  
                  {allHints[currentHintLevel].isAI && (
                    <div className="mt-3 pt-3 border-t border-primary-200">
                      <div className="flex items-center space-x-2">
                        <Icon name="Sparkles" size={14} className="text-primary" />
                        <span className="text-xs text-primary-600 font-medium">
                          AI-generated based on your learning pattern
                        </span>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* Hint Usage Statistics */}
          <div className="mt-6 p-4 bg-surface-50 rounded-lg border border-border">
            <div className="flex items-center justify-between mb-3">
              <h4 className="font-medium text-text-primary">Hint Usage</h4>
              <span className="text-sm text-text-secondary">
                {usedHints.length} of {allHints.length} used
              </span>
            </div>
            
            <div className="w-full bg-surface-100 rounded-full h-2">
              <div 
                className="h-2 rounded-full transition-all duration-500"
                style={{ 
                  width: `${(usedHints.length / allHints.length) * 100}%`,
                  backgroundColor: uiAdaptations.accentColor
                }}
              ></div>
            </div>
            
            <p className="text-xs text-text-secondary mt-2">
              Using hints helps the AI understand your learning style better
            </p>
          </div>

          {/* Related Topics */}
          <div className="mt-6">
            <h4 className="font-medium text-text-primary mb-3">
              Related Topics to Explore
            </h4>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {[
                { name: 'Chain Rule', difficulty: 'Intermediate' },
                { name: 'Product Rule', difficulty: 'Intermediate' },
                { name: 'Implicit Differentiation', difficulty: 'Advanced' },
                { name: 'Applications of Derivatives', difficulty: 'Advanced' }
              ].map((topic, index) => (
                <div key={index} className="p-3 bg-surface-50 rounded-lg border border-border">
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-medium text-text-primary">
                      {topic.name}
                    </span>
                    <span className={`text-xs px-2 py-1 rounded-full ${
                      topic.difficulty === 'Advanced' ?'bg-error-50 text-error-600' :'bg-warning-50 text-warning-600'
                    }`}>
                      {topic.difficulty}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between p-6 border-t border-border">
          <div className="flex items-center space-x-2 text-text-secondary">
            <Icon name="Info" size={16} />
            <span className="text-sm">
              Hints are personalized based on your learning progress
            </span>
          </div>
          
          <button
            onClick={onClose}
            className="btn btn-primary px-6 py-2"
          >
            Continue Learning
          </button>
        </div>
      </div>
    </div>
  );
};

export default HintSystem;