import React, { useState, useRef, useEffect } from 'react';
import Icon from 'components/AppIcon';

const NoteTaking = ({ notes, onAddNote, onClose, uiAdaptations }) => {
  const [newNote, setNewNote] = useState('');
  const [selectedNote, setSelectedNote] = useState(null);
  const [noteType, setNoteType] = useState('text'); // 'text', 'sketch', 'voice'
  const [isRecording, setIsRecording] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const textareaRef = useRef(null);
  const canvasRef = useRef(null);

  const filteredNotes = notes.filter(note =>
    note.content.toLowerCase().includes(searchQuery.toLowerCase()) ||
    note.topic.toLowerCase().includes(searchQuery.toLowerCase())
  );

  useEffect(() => {
    if (textareaRef.current && noteType === 'text') {
      textareaRef.current.focus();
    }
  }, [noteType]);

  const handleAddNote = () => {
    if (newNote.trim()) {
      onAddNote(newNote.trim());
      setNewNote('');
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
      handleAddNote();
    }
  };

  const startVoiceRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      setIsRecording(true);
      // In a real implementation, you would use Web Speech API or similar
      setTimeout(() => {
        setIsRecording(false);
        setNewNote(prev => prev + ' [Voice note recorded]');
      }, 3000);
    } catch (error) {
      console.error('Voice recording failed:', error);
    }
  };

  const initializeSketch = () => {
    if (canvasRef.current) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      ctx.strokeStyle = uiAdaptations.accentColor;
      ctx.lineWidth = 2;
      ctx.lineCap = 'round';
    }
  };

  const formatTimestamp = (timestamp) => {
    return new Date(timestamp).toLocaleString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const getTextSize = () => {
    switch (uiAdaptations.textSize) {
      case 'large':
        return 'text-lg leading-relaxed';
      case 'small':
        return 'text-sm leading-normal';
      default:
        return 'text-base leading-relaxed';
    }
  };

  const getContrastClass = () => {
    return uiAdaptations.contrast === 'high' ?'text-gray-900' :'text-text-primary';
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black bg-opacity-50">
      <div className="bg-surface rounded-xl border border-border shadow-warm-xl max-w-4xl w-full max-h-[90vh] overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-border">
          <div className="flex items-center space-x-3">
            <div 
              className="p-2 rounded-lg"
              style={{ backgroundColor: `${uiAdaptations.accentColor}20` }}
            >
              <Icon 
                name="PenTool" 
                size={20} 
                style={{ color: uiAdaptations.accentColor }}
              />
            </div>
            <div>
              <h2 className={`font-heading font-bold ${getContrastClass()} ${
                uiAdaptations.textSize === 'large' ? 'text-xl' : 'text-lg'
              }`}>
                Learning Notes
              </h2>
              <p className="text-sm text-text-secondary">
                {notes.length} notes • Synced across devices
              </p>
            </div>
          </div>
          
          <button
            onClick={onClose}
            className="p-2 text-text-secondary hover:text-text-primary hover:bg-surface-50 rounded-lg transition-colors duration-200"
          >
            <Icon name="X" size={20} />
          </button>
        </div>

        <div className="flex h-[calc(90vh-120px)]">
          {/* Notes List */}
          <div className="w-1/3 border-r border-border overflow-y-auto">
            {/* Search */}
            <div className="p-4 border-b border-border">
              <div className="relative">
                <Icon name="Search" size={16} className="absolute left-3 top-1/2 transform -translate-y-1/2 text-text-secondary" />
                <input
                  type="text"
                  placeholder="Search notes..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full pl-10 pr-4 py-2 bg-surface-50 border border-border rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent"
                />
              </div>
            </div>

            {/* Notes List */}
            <div className="p-2">
              {filteredNotes.length === 0 ? (
                <div className="text-center py-8">
                  <Icon name="FileText" size={32} className="text-text-tertiary mx-auto mb-2" />
                  <p className="text-sm text-text-secondary">
                    {searchQuery ? 'No notes found' : 'No notes yet'}
                  </p>
                </div>
              ) : (
                <div className="space-y-2">
                  {filteredNotes.map((note) => (
                    <button
                      key={note.id}
                      onClick={() => setSelectedNote(note)}
                      className={`w-full p-3 text-left rounded-lg border transition-all duration-200 ${
                        selectedNote?.id === note.id
                          ? 'border-primary bg-primary-50 text-primary-700' :'border-border bg-surface hover:bg-surface-50 text-text-primary'
                      }`}
                    >
                      <div className="flex items-start justify-between mb-1">
                        <span className="text-xs font-medium text-text-secondary">
                          {note.topic}
                        </span>
                        <span className="text-xs text-text-tertiary">
                          {formatTimestamp(note.timestamp)}
                        </span>
                      </div>
                      <p className="text-sm line-clamp-2">
                        {note.content}
                      </p>
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Note Editor */}
          <div className="flex-1 flex flex-col">
            {/* Note Type Selector */}
            <div className="p-4 border-b border-border">
              <div className="flex items-center space-x-2">
                <button
                  onClick={() => setNoteType('text')}
                  className={`p-2 rounded-lg transition-colors duration-200 ${
                    noteType === 'text' ?'bg-primary text-white' :'bg-surface-50 text-text-secondary hover:bg-surface-100'
                  }`}
                >
                  <Icon name="Type" size={16} />
                </button>
                <button
                  onClick={() => {
                    setNoteType('sketch');
                    setTimeout(initializeSketch, 100);
                  }}
                  className={`p-2 rounded-lg transition-colors duration-200 ${
                    noteType === 'sketch' ?'bg-primary text-white' :'bg-surface-50 text-text-secondary hover:bg-surface-100'
                  }`}
                >
                  <Icon name="Pen" size={16} />
                </button>
                <button
                  onClick={() => setNoteType('voice')}
                  className={`p-2 rounded-lg transition-colors duration-200 ${
                    noteType === 'voice' ?'bg-primary text-white' :'bg-surface-50 text-text-secondary hover:bg-surface-100'
                  }`}
                >
                  <Icon name="Mic" size={16} />
                </button>
                
                <div className="flex-1"></div>
                
                <span className="text-xs text-text-secondary">
                  {noteType === 'text' && 'Ctrl+Enter to save'}
                  {noteType === 'sketch' && 'Draw to take visual notes'}
                  {noteType === 'voice' && 'Record voice notes'}
                </span>
              </div>
            </div>

            {/* Editor Content */}
            <div className="flex-1 p-4">
              {noteType === 'text' && (
                <div className="h-full flex flex-col">
                  <textarea
                    ref={textareaRef}
                    value={newNote}
                    onChange={(e) => setNewNote(e.target.value)}
                    onKeyDown={handleKeyPress}
                    placeholder="Start typing your note... (Ctrl+Enter to save)"
                    className={`flex-1 w-full p-4 border border-border rounded-lg resize-none focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent ${getTextSize()}`}
                    style={{
                      fontSize: uiAdaptations.textSize === 'large' ? '16px' : '14px'
                    }}
                  />
                </div>
              )}

              {noteType === 'sketch' && (
                <div className="h-full flex flex-col">
                  <canvas
                    ref={canvasRef}
                    width={600}
                    height={400}
                    className="flex-1 border border-border rounded-lg bg-white cursor-crosshair"
                  />
                  <div className="flex items-center justify-between mt-3">
                    <div className="flex items-center space-x-2">
                      <button className="p-2 bg-surface-50 rounded-lg hover:bg-surface-100">
                        <Icon name="Eraser" size={16} className="text-text-secondary" />
                      </button>
                      <button className="p-2 bg-surface-50 rounded-lg hover:bg-surface-100">
                        <Icon name="Palette" size={16} className="text-text-secondary" />
                      </button>
                    </div>
                    <button
                      onClick={() => {
                        // Save sketch as note
                        onAddNote('[Sketch note created]');
                        setNoteType('text');
                      }}
                      className="btn btn-primary px-4 py-2"
                    >
                      Save Sketch
                    </button>
                  </div>
                </div>
              )}

              {noteType === 'voice' && (
                <div className="h-full flex flex-col items-center justify-center">
                  <div className={`w-32 h-32 rounded-full flex items-center justify-center mb-6 ${
                    isRecording ? 'bg-error-50 animate-pulse' : 'bg-surface-50'
                  }`}>
                    <Icon 
                      name="Mic" 
                      size={48} 
                      className={isRecording ? 'text-error' : 'text-text-secondary'}
                    />
                  </div>
                  
                  <button
                    onClick={startVoiceRecording}
                    disabled={isRecording}
                    className={`btn px-6 py-3 ${
                      isRecording 
                        ? 'bg-error text-white cursor-not-allowed' :'btn-primary'
                    }`}
                  >
                    {isRecording ? 'Recording...' : 'Start Recording'}
                  </button>
                  
                  <p className="text-sm text-text-secondary mt-4 text-center">
                    {isRecording 
                      ? 'Speak clearly. Recording will stop automatically.' :'Click to start recording a voice note'
                    }
                  </p>
                </div>
              )}
            </div>

            {/* Action Buttons */}
            {noteType === 'text' && (
              <div className="p-4 border-t border-border">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-2 text-text-secondary">
                    <Icon name="Info" size={16} />
                    <span className="text-sm">
                      Notes are automatically synced and searchable
                    </span>
                  </div>
                  
                  <div className="flex space-x-2">
                    <button
                      onClick={() => setNewNote('')}
                      className="btn btn-outline px-4 py-2"
                    >
                      Clear
                    </button>
                    <button
                      onClick={handleAddNote}
                      disabled={!newNote.trim()}
                      className="btn btn-primary px-6 py-2"
                    >
                      Save Note
                    </button>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Note Preview */}
          {selectedNote && (
            <div className="w-1/3 border-l border-border overflow-y-auto">
              <div className="p-4 border-b border-border">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-medium text-text-secondary">
                    {selectedNote.topic}
                  </span>
                  <button className="p-1 text-text-secondary hover:text-text-primary">
                    <Icon name="MoreHorizontal" size={16} />
                  </button>
                </div>
                <span className="text-xs text-text-tertiary">
                  {formatTimestamp(selectedNote.timestamp)}
                </span>
              </div>
              
              <div className="p-4">
                <div className={`${getTextSize()} ${getContrastClass()}`}>
                  {selectedNote.content.split('\n').map((line, index) => (
                    <p key={index} className="mb-2 last:mb-0">
                      {line}
                    </p>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default NoteTaking;