import React, { useState, useEffect } from 'react';
import Icon from 'components/AppIcon';


const ContentRenderer = ({ content, uiAdaptations, onInteraction }) => {
  const [currentSection, setCurrentSection] = useState(0);
  const [interactionData, setInteractionData] = useState({});
  const [readingProgress, setReadingProgress] = useState(0);

  const sections = content.content.split('\n\n');

  useEffect(() => {
    // Simulate reading progress tracking
    const timer = setTimeout(() => {
      if (readingProgress < 100) {
        setReadingProgress(prev => Math.min(prev + 10, 100));
      }
    }, 2000);

    return () => clearTimeout(timer);
  }, [readingProgress]);

  const handleInteractiveElement = (element, value) => {
    setInteractionData(prev => ({
      ...prev,
      [element.label]: value
    }));
    onInteraction(85); // Update performance based on interaction
  };

  const getTextSize = () => {
    switch (uiAdaptations.textSize) {
      case 'large':
        return 'text-lg leading-relaxed';
      case 'small':
        return 'text-sm leading-normal';
      default:
        return 'text-base leading-relaxed';
    }
  };

  const getContrastClass = () => {
    return uiAdaptations.contrast === 'high' ?'text-gray-900' :'text-text-primary';
  };

  return (
    <div className="space-y-6">
      {/* Content Header */}
      <div className="flex items-center justify-between">
        <h2 className={`font-heading font-bold ${getContrastClass()} ${
          uiAdaptations.textSize === 'large' ? 'text-2xl' : 'text-xl'
        }`}>
          {content.title}
        </h2>
        
        <div className="flex items-center space-x-2">
          <div className="w-16 bg-surface-100 rounded-full h-1">
            <div 
              className="h-1 rounded-full transition-all duration-500"
              style={{ 
                width: `${readingProgress}%`,
                backgroundColor: uiAdaptations.accentColor
              }}
            ></div>
          </div>
          <span className="text-xs text-text-secondary">{readingProgress}%</span>
        </div>
      </div>

      {/* Main Content */}
      <div className="space-y-6">
        {sections.map((section, index) => (
          <div 
            key={index}
            className={`transition-all duration-500 ${
              currentSection === index ? 'opacity-100' : 'opacity-70'
            } ${uiAdaptations.reducedMotion ? '' : 'animate-fade-in'}`}
          >
            <p className={`${getTextSize()} ${getContrastClass()} mb-4`}>
              {section}
            </p>
            
            {/* Visual Elements */}
            {content.visualElements && index === 1 && (
              <div className="my-6 p-4 bg-surface-50 rounded-lg border border-border">
                <div className="flex items-center space-x-3 mb-4">
                  <Icon name="BarChart3" size={20} className="text-primary" />
                  <span className="font-medium text-text-primary">Interactive Visualization</span>
                </div>
                
                {/* Mock Graph Visualization */}
                <div className="relative h-48 bg-white rounded-lg border border-border p-4">
                  <svg className="w-full h-full" viewBox="0 0 400 160">
                    {/* Grid lines */}
                    <defs>
                      <pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse">
                        <path d="M 20 0 L 0 0 0 20" fill="none" stroke="#E5E7EB" strokeWidth="1"/>
                      </pattern>
                    </defs>
                    <rect width="100%" height="100%" fill="url(#grid)" />
                    
                    {/* Function curve */}
                    <path
                      d="M 20 140 Q 100 120 200 80 T 380 40"
                      fill="none"
                      stroke={uiAdaptations.accentColor}
                      strokeWidth="3"
                    />
                    
                    {/* Tangent line */}
                    <line
                      x1="150"
                      y1="60"
                      x2="250"
                      y2="100"
                      stroke="#F59E0B"
                      strokeWidth="2"
                      strokeDasharray="5,5"
                    />
                    
                    {/* Point of tangency */}
                    <circle
                      cx="200"
                      cy="80"
                      r="4"
                      fill="#EF4444"
                    />
                  </svg>
                  
                  <div className="absolute top-2 right-2 text-xs text-text-secondary">
                    f(x) and f'(x) at point x
                  </div>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Interactive Elements */}
      {content.interactiveElements && (
        <div className="space-y-4">
          <h3 className={`font-heading font-semibold ${getContrastClass()} ${
            uiAdaptations.textSize === 'large' ? 'text-lg' : 'text-base'
          }`}>
            Interactive Exploration
          </h3>
          
          {content.interactiveElements.map((element, index) => (
            <div key={index} className="p-4 bg-primary-50 rounded-lg border border-primary-200">
              <div className="flex items-center justify-between mb-3">
                <label className="text-sm font-medium text-text-primary">
                  {element.label}
                </label>
                <span className="text-xs text-text-secondary">
                  {interactionData[element.label] || 0}
                </span>
              </div>
              
              <input
                type="range"
                min="0"
                max="100"
                value={interactionData[element.label] || 50}
                onChange={(e) => handleInteractiveElement(element, e.target.value)}
                className="w-full h-2 bg-surface-100 rounded-lg appearance-none cursor-pointer slider"
                style={{
                  background: `linear-gradient(to right, ${uiAdaptations.accentColor} 0%, ${uiAdaptations.accentColor} ${interactionData[element.label] || 50}%, #F3F4F6 ${interactionData[element.label] || 50}%, #F3F4F6 100%)`
                }}
              />
              
              <p className="text-xs text-text-secondary mt-2">
                {element.action.replace('-', ' ').replace(/\b\w/g, l => l.toUpperCase())}
              </p>
            </div>
          ))}
        </div>
      )}

      {/* Comprehension Check */}
      <div className="mt-8 p-4 bg-surface-50 rounded-lg border border-border">
        <div className="flex items-center space-x-3 mb-3">
          <Icon name="CheckCircle" size={20} className="text-success" />
          <span className="font-medium text-text-primary">Quick Comprehension Check</span>
        </div>
        
        <p className={`${getTextSize()} ${getContrastClass()} mb-4`}>
          Can you explain in your own words what a derivative represents?
        </p>
        
        <textarea
          className="w-full p-3 border border-border rounded-lg resize-none focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent"
          rows="3"
          placeholder="Type your understanding here..."
          style={{
            fontSize: uiAdaptations.textSize === 'large' ? '16px' : '14px'
          }}
        ></textarea>
        
        <div className="flex items-center justify-between mt-3">
          <span className="text-xs text-text-secondary">
            This helps AI understand your learning progress
          </span>
          <button 
            className="btn btn-primary px-4 py-2 text-sm"
            onClick={() => onInteraction(90)}
          >
            Submit
          </button>
        </div>
      </div>

      {/* Navigation Hints */}
      <div className="flex items-center justify-between pt-6 border-t border-border">
        <div className="flex items-center space-x-2 text-text-secondary">
          <Icon name="Lightbulb" size={16} />
          <span className="text-sm">
            {uiAdaptations.cognitiveLoad === 'reduced' ?'Take your time to understand each concept' :'Ready for the next challenge?'
            }
          </span>
        </div>
        
        <div className="flex items-center space-x-2">
          <button
            onClick={() => setCurrentSection(Math.max(0, currentSection - 1))}
            disabled={currentSection === 0}
            className="p-2 text-text-secondary hover:text-text-primary disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Icon name="ChevronUp" size={16} />
          </button>
          <button
            onClick={() => setCurrentSection(Math.min(sections.length - 1, currentSection + 1))}
            disabled={currentSection === sections.length - 1}
            className="p-2 text-text-secondary hover:text-text-primary disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Icon name="ChevronDown" size={16} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ContentRenderer;